var response = await client.Variations.ListVariationsAsync(
    new Dictionary<string, object?> { ["search"] = "size", ["standard"] = "text" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var variation in ((IReadOnlyList<object?>)body["variations"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{variation["id"]} {variation["name"]} {variation["standard"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

