var response = await client.Variations.ListProductVariationsAsync(4321);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var group in ((IReadOnlyList<object?>)body["variations"]!).Cast<IReadOnlyDictionary<string, object?>>())
{
    Console.WriteLine(group["product_key"]);
    foreach (var variant in ((IReadOnlyList<object?>)group["variants"]!).Cast<IReadOnlyDictionary<string, object?>>())
        Console.WriteLine($"{variant["variation_id"]} {variant["key"]} {variant["available"]}");
}

